const query = new URLSearchParams(location.search);
const localPreview = location.protocol === 'file:' || ['localhost','127.0.0.1','[::1]'].includes(location.hostname);
const state = {
  variant: ['A','B','C'].includes(query.get('variant')) ? query.get('variant') : 'A',
  lang: query.get('lang') === 'en' ? 'en' : 'ar',
  screen: ['form','correction','queue','review','gallery'].includes(query.get('screen')) ? query.get('screen') : 'form',
  page: 1, filter: 'all', search: '', sort: 'newest', error: false,
  fields: {amount:'200000',term:'6',budget:'250000',explanation:'',correctionAmount:'600000'},
  replacement: false, focus: '', document: 3,
};
const $ = s => document.querySelector(s);
const t = (ar,en) => state.lang === 'ar' ? ar : en;
const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const ltr = value => `<bdi dir="ltr">${esc(value)}</bdi>`;
const entered = value => `<bdi dir="auto">${esc(value)}</bdi>`;
const digits = value => String(value).replace(/[٠-٩]/g, c => '٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c));
const num = value => new Intl.NumberFormat('en-US').format(value);
const money = value => `${ltr(num(value))}<span class="currency">${t('ر.ي.','YER')}</span>`;
const date = value => new Intl.DateTimeFormat(state.lang==='ar'?'ar-YE-u-nu-latn':'en-GB', {day:'numeric',month:'short',year:'numeric',calendar:'gregory',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));
const icon = name => {
  const paths = {
    form:'<path d="M7 3h10l3 3v15H4V3zM8 9h8M8 13h8M8 17h5"/>',
    queue:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12M13 13h4M13 17h4"/>',
    review:'<path d="M8 3h8l3 3v8M5 3v18h9M8 9h7M8 13h3M14 18l3 3 5-7"/>',
    correction:'<path d="M19 8a8 8 0 1 0 1 7M19 3v6h-6M8 12h7M8 16h4"/>',
    gallery:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
    file:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 13h7M9 17h5"/>',
    eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 6 6 12 0 18-6-6-6-12 0-18Z"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  };
  return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
};
