const btn = (label,action,cls='',attrs='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const head = (title,subtitle,aside='') => `<header class="page-head"><div><div class="eyebrow">${t('رِفد / منصة تمويل تجريبية','RIFD / FICTIONAL FINANCING')}</div><h1>${title}</h1><p>${subtitle}</p></div>${aside?`<div class="row">${aside}</div>`:''}</header>`;
const definition = (label,value) => `<div class="definition"><dt>${label}</dt><dd>${value}</dd></div>`;
const steps = () => `<ol class="steps" aria-label="${t('خطوات الطلب','Application steps')}">${[t('بياناتك','Personal'),t('النشاط','Business'),t('التمويل','Financing'),t('المستندات','Documents'),t('التأكيد','Confirm')].map((s,i)=>`<li class="${i===2?'current':''}" ${i===2?'aria-current="step"':''}><span class="step-no">${i<2?'✓':i+1}</span><span>${s}</span></li>`).join('')}</ol>`;
const inputField = (key,label,hint='',extra='') => `<div class="field"><label for="${key}">${label} <span class="required" aria-hidden="true">*</span></label><input id="${key}" name="${key}" data-field="${key}" value="${esc(state.fields[key])}" inputmode="numeric" dir="ltr" required aria-describedby="${key}-hint" ${extra}><p id="${key}-hint" class="hint">${hint}</p></div>`;
function formFields(){
  return `<div class="fields">
    ${inputField('amount',t('مبلغ التمويل المطلوب','Requested amount'),`${money(100000)} ${t('إلى','to')} ${money(1000000)}`)}
    <div class="field"><label for="term">${t('مدة السداد','Repayment term')} <span class="required" aria-hidden="true">*</span></label><select id="term" data-field="term"><option value="6" ${state.fields.term==='6'?'selected':''}>6 ${t('أشهر','months')}</option><option value="12" ${state.fields.term==='12'?'selected':''}>12 ${t('شهراً','months')}</option></select><p class="hint">${t('اختر المدة المناسبة لنشاطك.','Choose the term for your business.')}</p></div>
    ${inputField('budget',t('تكلفة الشراء المتوقعة','Purchase budget'),t('التكلفة الكاملة لما تنوي شراءه، بالريال اليمني.','The full expected purchase cost, in YER.'))}
    <div class="field"><label for="business">${t('اسم النشاط التجاري','Business name')}</label><input id="business" value="متجر السهل التجريبي" dir="auto" readonly><p class="hint">${t('من خطوة بيانات النشاط.','From your business details.')}</p></div>
    <div class="field full"><label for="explanation">${t('وصف الشراء والغرض منه','Purchase explanation')} <span class="required" aria-hidden="true">*</span></label><textarea id="explanation" data-field="explanation" dir="auto" required aria-describedby="explanation-hint${state.error?' explanation-error':''}" ${state.error?'aria-invalid="true"':''} placeholder="${t('صف ما تنوي شراءه وكيف يخدم نشاطك.','Describe what you plan to buy and how it serves your business.')}">${esc(state.fields.explanation)}</textarea><p id="explanation-hint" class="hint">${t('من 20 إلى 500 حرف.','20 to 500 characters.')}</p>${state.error?`<p id="explanation-error" class="error-text">${t('أدخل وصفاً للشراء من 20 إلى 500 حرف للمتابعة.','Enter a purchase explanation of 20 to 500 characters to continue.')}</p>`:''}</div>
  </div>`;
}
function summary(){
  const n = Number(digits(state.fields.amount).replaceAll(',',''));
  const amount = Number.isFinite(n)&&n>=0?n:0;
  const markup = Math.floor(amount*.05+.5), term=Number(state.fields.term), total=amount+markup, first=Math.floor(total/term), last=total-first*(term-1);
  return `<section class="panel summary-card"><div class="eyebrow">${t('ملخص التمويل','FINANCING SUMMARY')}</div><h2>${product('inventory')}</h2><p class="amount">${money(amount)}</p><p class="mini-label">${t('مبلغ التمويل قبل الإضافة التوضيحية','Financing amount before illustrative markup')}</p><div class="rule"></div><dl>${definition(t('إضافة توضيحية 5%','Illustrative markup, 5%'),money(markup))}${definition(t('إجمالي السداد','Repayment total'),money(total))}${definition(t('عدد الأقساط','Installments'),ltr(term))}${definition(t('القسط الشهري التوضيحي','Illustrated monthly installment'),money(first))}${last!==first?definition(t('القسط الأخير','Final installment'),money(last)):''}</dl><p class="small muted" style="margin-top:20px">${t('حساب خيالي لعرض الواجهة. لا يمثل عرض تمويل أو رسوماً فعلية.','Fictional illustration for this portfolio. These are not real financing terms or charges.')}</p></section>`;
}
function formPanel(){return `<section class="panel"><div class="section-title"><div><h2>${t('ما الذي يحتاجه نشاطك؟','What does your business need?')}</h2><p class="muted small">${t('أخبرنا بما تنوي شراءه ومبلغ التمويل المطلوب.','Tell us what you plan to buy and how much financing you need.')}</p></div><span class="tag">${ltr("3 / 5")}</span></div>${state.error?`<div class="notice error" role="alert" style="margin-bottom:20px"><a href="#explanation">${t('راجع وصف الشراء قبل المتابعة.','Review the purchase explanation before continuing.')}</a></div>`:''}${formFields()}<div class="actions">${btn(t('حفظ المسودة','Save draft'),'save')}${btn(t('متابعة إلى المستندات','Continue to documents'),'validate','primary')}</div><p class="small muted" style="margin-top:14px">${t('يمكن حفظ المسودة حتى لو لم تكتمل المعلومات.','You can save a draft with incomplete information.')}</p></section>`;}
const applicantCard = () => `<section class="panel"><p class="mini-label">${t('مقدم الطلب','Applicant')}</p><h3>${entered('مريم سالم')}</h3><p class="small muted">${entered('عدن')} · ${ltr('+000000000001')}</p><div class="rule"></div><p class="small">${t('4 مستندات محفوظة في المسودة','4 documents saved with the draft')}</p><p class="small muted">${t('هوية، نشاط، ملخص مالي، وخطة شراء المخزون.','Identity, business evidence, financial summary, and stock purchase plan.')}</p>${btn(t('معاينة المستندات','Preview documents'),'applicant-docs','small quiet')}</section>`;
function application(){
  const intro=head(t('تفاصيل التمويل','Financing details'),t('مسودة مريم سالم · يمكنك إكمال الطلب على مهل.','Mariam Salem’s draft · Continue at your own pace.'),badge('draft'));
  if(state.variant==='B') return intro+`<div class="book-layout"><aside><div class="chapter-number">03</div>${steps()}<p class="small muted">${t('معلوماتك تبقى كما أدخلتها عند تبديل اللغة.','Your entered text stays as entered when you switch language.')}</p></aside><div>${formPanel()}</div><aside class="stack">${summary()}${applicantCard()}</aside></div>`;
  if(state.variant==='C') return intro+`<div class="console-form"><aside>${steps()}</aside><div>${formPanel()}</div><aside class="stack">${summary()}${applicantCard()}</aside></div>`;
  return intro+steps()+`<div class="main-grid"><div>${formPanel()}</div><aside class="stack">${summary()}${applicantCard()}</aside></div>`;
}
function correction(){
  return head(t('عدّل نقطتين لإكمال المراجعة','Two changes to continue the review'),`${ltr('RF-2026-1003')} · ${entered('متجر الندى التجريبي')}`,badge('corrections'))+`<div class="main-grid"><section class="panel"><div class="notice warning" style="margin-bottom:25px">${t('طُلبت هذه التعديلات في 4 أكتوبر 2026. يمكنك تعديل البنود المحددة فقط.','Requested on 4 October 2026. You can edit only the requested items.')}</div><div class="correction-target"><h3>01 · ${t('تخفيض مبلغ التمويل المطلوب','Reduce the requested financing amount')}</h3><p>${t('القسط التوضيحي الحالي 105,000 ر.ي. يتجاوز حد القدرة على السداد البالغ 80,000 ر.ي. يرجى تخفيض مبلغ التمويل المطلوب.','The current illustrated installment of 105,000 YER exceeds the 80,000 YER capacity limit. Please reduce the requested financing amount.')}</p>${inputField('correctionAmount',t('مبلغ التمويل المطلوب','Requested amount'),`${t('المبلغ المُقدّم','Submitted amount')}: ${money(600000)}`)}</div><div class="correction-target"><h3>02 · ${t('استبدال خطة شراء المخزون','Replace the stock purchase plan')}</h3><p>${t('أرفق خطة شراء واضحة يمكن قراءتها، تبين المستلزمات المنزلية المطلوب شراؤها والتكلفة الكاملة.','Supply a readable stock purchase plan showing the household supplies you plan to buy and their total cost.')}</p><div class="doc-row"><div class="file-icon">${icon('file')}</div><div class="grow"><h3>${t('خطة شراء المخزون','Stock purchase plan')}</h3><div class="filename">${ltr(state.replacement?'stock_خطة-readable.pdf':'stock_خطة-original.pdf')}</div><span class="tag">${state.replacement?t('بديل مُجهّز، غير محفوظ','Replacement prepared, unsaved'):t('الملف المُقدّم سابقاً','Previously submitted file')}</span></div>${btn(icon('eye')+t('معاينة','Preview'),'stock-preview','small')}${btn(t('تجهيز مثال بديل','Prepare sample replacement'),'replacement','small')}</div><p class="small muted">${t('PDF أو JPEG أو PNG، حتى 5 MB للملف.','PDF, JPEG or PNG, up to 5 MB per file.')}</p></div><div class="actions">${btn(t('حفظ التعديلات','Save changes'),'save')}${btn(t('إعادة إرسال التعديلات','Resubmit corrections'),'resubmit','primary')}</div></section><aside class="stack"><section class="panel summary-card"><h2>${t('ما الذي سيُرسل؟','What will be sent?')}</h2><p>${t('المبلغ الجديد وخطة الشراء البديلة فقط. باقي بيانات الطلب ثابتة.','The new amount and replacement purchase plan. The other application information stays fixed.')}</p><div class="rule"></div><p class="small">${t('الحفظ الجزئي لا يرسل التعديلات للمراجع. تُرسل بعد اكتمالها وإعادة إرسالها.','Saving unfinished changes does not publish them to the reviewer. A completed resubmission does.')}</p></section><section class="panel"><h3>${t('بيانات الطلب','Application details')}</h3><dl>${definition(t('مقدم الطلب','Applicant'),entered('هدى علي'))}${definition(t('المنتج','Product'),product('inventory'))}${definition(t('مدة السداد','Repayment term'),t('6 أشهر','6 months'))}${definition(t('تكلفة الشراء المتوقعة','Purchase budget'),money(650000))}</dl></section></aside></div>`;
}
const counts = () => `<div class="queue-counts">${[[t('جميع الطلبات','All applications'),12],[statusText('submitted'),4],[statusText('review'),3],[statusText('corrections'),3]].map(([label,n])=>`<div class="count"><span>${label}</span><strong>${n}</strong></div>`).join('')}</div>`;
function filtered(){return records.filter(r=>(state.filter==='all'||r.status===state.filter)&&`${r.id} ${r.name} ${r.business}`.toLowerCase().includes(state.search.trim().toLowerCase())).sort((a,b)=>state.sort==='amount'?b.amount-a.amount: b.date.localeCompare(a.date)||a.id.localeCompare(b.id));}
function queueToolbar(){return `<div class="toolbar"><div class="search">${icon('search')}<input id="queue-search" value="${esc(state.search)}" placeholder="${t('ابحث بالاسم أو رقم الطلب','Search name or application ID')}" aria-label="${t('بحث الطلبات','Search applications')}" dir="auto"></div><select id="status-filter" aria-label="${t('حالة الطلب','Application status')}"><option value="all">${t('جميع الحالات','All statuses')}</option>${['submitted','review','corrections','approved','rejected'].map(s=>`<option value="${s}" ${state.filter===s?'selected':''}>${statusText(s)}</option>`).join('')}</select><select id="queue-sort" aria-label="${t('ترتيب الطلبات','Sort applications')}"><option value="newest">${t('الأحدث أولاً','Newest first')}</option><option value="amount" ${state.sort==='amount'?'selected':''}>${t('المبلغ الأعلى','Highest amount')}</option></select></div>`;}
function queueRows(rows){return `<div class="table-wrap"><table><caption class="mini-label" style="text-align:start;padding:12px 16px">${t('طلبات التمويل المُقدّمة','Submitted financing applications')}</caption><thead><tr>${[t('الطلب / المتقدم','Application / applicant'),t('المنتج / المبلغ','Product / amount'),t('الحالة','Status'),t('المراجع','Reviewer'),t('تاريخ التقديم','Submitted'),t('الإجراء','Action')].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><div class="person-name">${entered(r.name)}</div><div class="person-business">${entered(r.business)}</div><div class="small muted">${ltr(r.id)}</div></td><td><div>${product(r.product)}</div><strong>${money(r.amount)}</strong></td><td>${badge(r.status)}</td><td>${assignment(r.owner)}</td><td>${date(r.date)}</td><td>${btn(t('فتح','Open'),'record','small',`data-id="${r.id}" aria-label="${t('فتح الطلب','Open application')} ${r.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-rows">${rows.map(r=>`<article class="queue-card"><div class="row between"><strong>${entered(r.name)}</strong>${badge(r.status)}</div><p class="small muted">${entered(r.business)}</p><p class="small muted">${ltr(r.id)} · ${date(r.date)}</p><div class="rule"></div><div class="row between"><div><p class="small">${product(r.product)}</p><strong>${money(r.amount)}</strong></div>${btn(t('فتح الطلب','Open'),'record','small',`data-id="${r.id}"`)}</div><p class="small muted" style="margin-top:12px">${assignment(r.owner)}</p></article>`).join('')}</div>`;}
function ledgerRows(rows){return [...new Set(rows.map(r=>r.status))].map(s=>`<div class="ledger-group">${badge(s)}<span class="small muted">${t('في هذه الصفحة','On this page')}</span></div>${rows.filter(r=>r.status===s).map(r=>`<article class="ledger-row"><div class="ledger-no">${String(rows.indexOf(r)+1).padStart(2,'0')}</div><div><div class="person-name">${entered(r.name)}</div><div class="person-business">${entered(r.business)}</div><div class="small muted">${ltr(r.id)}</div></div><div><div class="small muted">${product(r.product)}</div><strong>${money(r.amount)}</strong></div><div><div class="small muted">${date(r.date)}</div><div class="small">${assignment(r.owner)}</div>${btn(t('فتح الطلب','Open'),'record','small quiet',`data-id="${r.id}"`)}</div></article>`).join('')}`).join('');}
function queue(){
  const all=filtered(), pages=Math.max(1,Math.ceil(all.length/5));state.page=Math.min(state.page,pages);const rows=all.slice((state.page-1)*5,state.page*5);
  const content=queueToolbar()+(!rows.length?`<div class="empty">${t('لا توجد طلبات تطابق البحث.','No applications match your search.')}</div>`:state.variant==='B'?ledgerRows(rows):queueRows(rows))+`<div class="queue-footer"><span>${ltr(all.length?`${(state.page-1)*5+1}–${Math.min(state.page*5,all.length)}`:'0')} ${t('من','of')} ${all.length}</span><div class="pager" aria-label="${t('صفحات الطلبات','Queue pages')}">${Array.from({length:pages},(_,i)=>`<button data-action="page" data-page="${i+1}" aria-label="${t('الصفحة','Page')} ${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}</div><span>${t('5 طلبات لكل صفحة','5 per page')}</span></div>`;
  const intro=head(t('طلبات التمويل','Financing applications'),t('راجعي الطلبات، وتابعي ما يحتاج إلى إجراء.','Review applications and see what needs attention.'),`<span class="small muted">${date('2026-10-14')}</span>`);
  return intro+(state.variant==='B'?`<div class="queue-layout"><div>${content}</div><aside>${counts()}<section class="panel"><h2>${t('نظرة على العمل','At a glance')}</h2><p class="small muted">${t('7 طلبات مسندة إليك. طلبان بانتظار الإسناد.','7 applications assigned to you. 2 await assignment.')}</p><div class="rule"></div><p class="small muted">${t('تُجمع نتائج كل صفحة حسب الحالة في هذا الاتجاه.','This direction groups each page’s results by status.')}</p></section></aside></div>`:counts()+content);
}
function documentRows(applicant=false){return docs.map((d,i)=>`<div class="doc-row"><div class="file-icon">${icon('file')}</div><div class="grow"><h3>${t(...d.label)}</h3><div class="filename">${ltr(d.file)} · ${ltr(d.size)}</div>${applicant?`<span class="tag">${t('محفوظ في المسودة','Saved with draft')}</span>`:badge(d.status)}</div>${btn(icon('eye')+t('معاينة','Preview'),'doc','small',`data-doc="${i}" aria-label="${t('معاينة','Preview')} ${t(...d.label)}"`)}</div>`).join('');}
function documentSheet(index=3){
  const d=docs[index];
  const details=index===3?`<p class="muted small">${t('المورّد التجريبي / Demo Supplier','Demo Supplier / المورّد التجريبي')}</p><table><thead><tr><th>${t('البيان','Description')}</th><th>${t('التكلفة','Cost')}</th></tr></thead><tbody><tr><td>${t('آلة طباعة للنشاط التجاري','Business printing equipment')}<br><span class="small muted">${ltr('PRINT-02')} · ${t('قطعة واحدة','1 unit')}</span></td><td>${money(1100000)}</td></tr></tbody></table><div class="doc-total"><p class="small muted">${t('التكلفة الكاملة','Total purchase cost')}</p><strong class="amount">${money(1100000)}</strong></div>`:
  index===2?`<p>${t('يوليو، أغسطس، سبتمبر 2026','July, August, September 2026')}</p><dl>${definition(t('متوسط الإيرادات الشهرية','Average monthly revenue'),money(900000))}${definition(t('متوسط مصروفات التشغيل','Average operating expenses'),money(650000))}</dl>`:
  index===1?`<dl>${definition(t('النشاط التجاري','Business'),entered('ورشة المدار التجريبية'))}${definition(t('العنوان','Address'),entered('شارع السوق، موقع تجريبي، عدن'))}${definition(t('شهر بدء النشاط','Operating since'),ltr('2024-03'))}</dl>`:`<dl>${definition(t('الاسم الكامل','Full name'),entered('مريم سالم'))}${definition(t('المدينة','City'),entered('عدن'))}</dl>`;
  return `<article class="paper-doc"><div class="row between"><span class="stamp">${t('تجريبي / DEMO','DEMO / تجريبي')}</span><span class="small muted">${ltr('RF-2026-1006')}</span></div><h2>${t(...d.label)}</h2><p class="small muted">${entered('مريم سالم')} · ${entered('ورشة المدار التجريبية')}</p><div class="rule"></div>${details}<footer>${t('مستند خيالي للعرض فقط. ليس وثيقة هوية أو مستنداً صادراً عن جهة حقيقية.','Fictional sample for presentation only. It is not an identity document or evidence issued by a real organization.')}</footer></article>`;
}
const reviewChecks = () => `<section class="panel"><div class="section-title"><h2>${t('قائمة المراجعة','Review checklist')}</h2><span class="tag">${ltr("1 / 5")}</span></div><div class="review-list">${[['اتساق المستندات والبيانات','Evidence consistency'],['مدة مزاولة النشاط','Operating history'],['ملاءمة غرض التمويل','Product purpose fit'],['تغطية تكلفة الشراء','Purchase budget coverage'],['القدرة على السداد','Repayment capacity']].map((s,i)=>`<div class="check-row"><span>${t(...s)}</span><span class="check-state ${i===1?'passed':''}"><span class="check-box">${i===1?'✓':''}</span>${i===1?t('مستوفٍ','Passed'):t('لم يُفحص','Unchecked')}</span></div>`).join('')}</div><p class="small muted" style="margin-top:18px">${t('يجب قبول المستندات واجتياز جميع الفحوص قبل الموافقة.','All required documents must be accepted and checks passed before approval.')}</p><div class="actions">${btn(t('طلب تعديلات','Request corrections'),'review-action')}${btn(t('الموافقة','Approve'),'review-action','primary','disabled')}</div></section>`;
const reviewNote = () => `<section class="panel"><label for="note"><strong>${t('ملاحظة داخلية','Internal note')}</strong></label><p class="small muted" style="margin:5px 0 12px">${t('تظهر لفريق المراجعة فقط.','Visible to reviewers only.')}</p><textarea id="note" dir="auto" placeholder="${t('أضف سياقاً للمراجعة…','Add context for the review…')}">${esc(state.note||'')}</textarea>${btn(t('إضافة الملاحظة','Add note'),'save','small','style="margin-top:12px"')}</section>`;
const reviewFacts = () => `<div class="review-facts"><div><p class="mini-label">${t('مبلغ التمويل','Financing amount')}</p><p class="amount">${money(900000)}</p></div><div><p class="mini-label">${t('مدة السداد','Repayment term')}</p><p class="amount">12 <span class="currency">${t('شهراً','months')}</span></p></div><div><p class="mini-label">${t('القسط التوضيحي','Illustrated installment')}</p><p class="amount">${money(81000)}</p></div></div>`;
function review(){
  const intro=head(`${entered('مريم سالم')}`,`${ltr('RF-2026-1006')} · ${entered('ورشة المدار التجريبية')} · ${product('equipment')}`,badge('review'));
  const ownership=`<div class="row between" style="margin-bottom:20px"><span class="small">${t('مسند إليك · سلمى ناصر','Assigned to you · Salma Nasser')}</span><span class="small muted">${t('بدأت المراجعة في','Review started')} ${date('2026-10-07')}</span></div>`;
  const info=`<section class="panel"><div class="section-title"><h2>${t('معلومات الطلب','Application information')}</h2><span class="tag">${t('آخر معلومات مُرسلة','Last submitted information')}</span></div>${reviewFacts()}<p>${entered('شراء آلة طباعة لاستخدامها في أعمال الورشة وتقديم خدمات الطباعة.')}</p><dl style="margin-top:18px">${definition(t('تكلفة الشراء المتوقعة','Purchase budget'),money(1100000))}${definition(t('الإضافة التوضيحية، 8%','Illustrative markup, 8%'),money(72000))}${definition(t('إجمالي السداد','Repayment total'),money(972000))}</dl></section>`;
  const evidence=`<section class="panel"><div class="section-title"><h2>${t('المستندات الداعمة','Supporting documents')}</h2><span class="tag">4</span></div>${documentRows()}</section>`;
  const preview=`<div><div class="document-tools"><h3>${t(...docs[state.document].label)}</h3>${btn(icon('eye')+t('تكبير','Expand'),'doc','small',`data-doc="${state.document}"`)}</div>${documentSheet(state.document)}<div class="actions">${btn(t('قبول المستند','Accept document'),'review-action','primary')}${btn(t('يحتاج إلى استبدال','Needs replacement'),'review-action')}</div></div>`;
  if(state.variant==='B') return intro+ownership+`<div class="review-layout"><div>${preview}${evidence}</div><aside class="stack">${info}${reviewChecks()}${reviewNote()}</aside></div>`;
  if(state.variant==='C') return intro+ownership+reviewFacts()+`<div class="review-layout"><aside>${evidence}</aside>${preview}<aside class="stack">${reviewChecks()}${reviewNote()}</aside></div>`;
  return intro+ownership+`<div class="main-grid"><div class="stack">${info}${evidence}</div><aside class="stack">${reviewChecks()}${reviewNote()}</aside></div>`;
}
function gallery(){return head(t('لغة الواجهة','Interface language'),t('عينات للمقارنة البصرية، واختبار لوحة المفاتيح، والنص المختلط.','Samples for visual comparison, keyboard use, and mixed-direction text.'))+`<div class="gallery-grid"><section class="panel"><h2>${t('الخط والهوية','Typography and identity')}</h2><p class="type-sample" style="margin:20px 0">${t('خطوة واضحة نحو تمويل نشاطك.','A clear next step for your business.')}</p><p class="small muted">${variants[state.variant].font}</p><div class="swatch-row"><div class="swatch" style="background:var(--accent)"></div><div class="swatch" style="background:var(--ink)"></div><div class="swatch" style="background:var(--wash)"></div><div class="swatch" style="background:var(--line)"></div></div><div class="rule"></div><p class="small">${t('رِفد / RIFD اسم مقترح لهوية أصلية لملف الأعمال. لا يمثل بنكاً أو جهة تمويل.','RIFD / رِفد is a proposed original portfolio identity. It does not represent a bank or financing provider.')}</p></section><section class="panel"><h2>${t('حالات الطلب','Application statuses')}</h2><div class="row" style="margin-top:20px">${['draft','submitted','review','corrections','approved','rejected'].map(badge).join('')}</div><div class="rule"></div><h3>${t('حالات مراجعة المستند','Document review statuses')}</h3><div class="row" style="margin-top:15px">${['missing','awaiting','accepted','replace'].map(badge).join('')}</div><p class="small muted" style="margin-top:20px">${t('الاسم المكتوب يوضح الحالة إلى جانب اللون.','Written labels identify each state alongside color.')}</p></section><section class="panel"><h2>${t('التركيز والتحقق','Focus and validation')}</h2><div class="row" style="margin:22px 3px">${btn(t('إجراء أساسي','Primary action'),'sample','primary forced-focus')}${btn(t('إجراء ثانوي','Secondary action'),'sample')}</div><div class="field"><label for="sample-amount">${t('مبلغ التمويل المطلوب','Requested amount')}</label><input id="sample-amount" dir="ltr" value="50,000" aria-invalid="true" aria-describedby="sample-error"><p id="sample-error" class="error-text">${t('أدخل مبلغاً بين 100,000 و1,000,000 ر.ي.','Enter an amount between 100,000 and 1,000,000 YER.')}</p></div><p class="small muted" style="margin-top:20px">${t('اضغط Tab للتنقل بين عناصر الواجهة. حلقة التركيز البنفسجية متعمدة في العينة.','Use Tab to move between controls. The purple focus ring is intentionally shown in this sample.')}</p></section><section class="panel"><h2>${t('نص عربي وأرقام لاتينية','Arabic text and Latin digits')}</h2><dl style="margin-top:16px">${definition(t('اسم النشاط','Business name'),entered('ورشة المدار / Al-Madar 02'))}${definition(t('رقم الطلب','Application ID'),ltr('RF-2026-1006'))}${definition(t('الجوال','Mobile'),ltr('+000000000001'))}${definition(t('الملف','File'),ltr('quotation_معدات-02.pdf'))}${definition(t('المبلغ','Amount'),money(1200000))}${definition(t('تاريخ العرض','Demo date'),date('2026-10-14'))}</dl><p class="small muted" style="margin-top:20px">${t('الاسم المختلط عينة طباعية فقط. بيانات المتقدمين لا تُترجم تلقائياً.','The mixed name is a typography sample only. Entered applicant text is never automatically translated.')}</p></section></div>`;}
function shell(content){
  const staff=['queue','review'].includes(state.screen), nav=staff?['queue','review']:['form','correction'];
  return `<div class="${staff?'staff':'applicant'}"><div class="disclosure">${t('مشروع لملف أعمال · هوية ومنتجات وبيانات خيالية','PORTFOLIO DEMO · Fictional identity, products and data')} <span>· ${t('لا يوجد تمويل حقيقي','No real financing')}</span></div><header class="topbar"><a href="?variant=${state.variant}&lang=${state.lang}&screen=form" class="brand" data-screen="form" aria-label="${t('رِفد، نموذج بصري','RIFD, visual prototype')}"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span><span><strong>${t('رِفد','RIFD')}</strong><small>${t('تمويل يساند نشاطك','FINANCING FOR YOUR BUSINESS')}</small></span></a><div class="row">${btn(icon('globe')+t('English','العربية'),'language','small')}<span class="avatar">${staff?t('س ن','SN'):state.screen==='correction'?t('هـ ع','HA'):t('م س','MS')}</span><div class="identity-name"><strong class="small">${staff?t('سلمى ناصر','Salma Nasser'):state.screen==='correction'?t('هدى علي','Huda Ali'):t('مريم سالم','Mariam Salem')}</strong><div class="small muted">${staff?t('مراجِعة تجريبية','Demo reviewer'):t('متقدمة تجريبية','Demo applicant')}</div></div></div></header><div class="workspace"><aside class="side"><p class="side-label">${staff?t('مساحة المراجعة','REVIEW WORKSPACE'):t('مساحة المتقدم','APPLICANT WORKSPACE')}</p><nav class="nav" aria-label="${t('التنقل','Navigation')}">${nav.map(k=>`<button data-screen="${k}" ${state.screen===k?'aria-current="page"':''}>${icon(k)}<span>${labels[k]()}</span></button>`).join('')}</nav><div class="side-foot">${t('نموذج تصميم قابل للمقارنة.','A design comparison prototype.')}<br>${t('14 أكتوبر 2026','14 October 2026')}</div></aside><main class="main" id="main" tabindex="-1">${content}<footer class="sample-state"><span>${t('نموذج بصري مؤقت','Throwaway visual prototype')}</span> · ${ltr(state.variant)} · ${labels[state.screen]()} · ${ltr(state.lang==='ar'?'RTL / ar':'LTR / en')} · ${t('تعديلات في الذاكرة فقط؛ لا يوجد حفظ أو إرسال.','Edits in memory only; no saving or submission.')}<br>${state.screen==='form'?`${t('الحالة المعروضة','Displayed state')}: Draft · Inventory · ${esc(state.fields.amount)} YER · ${esc(state.fields.term)} months`:state.screen==='review'?`${t('الحالة المعروضة','Displayed state')}: ${ltr('RF-2026-1006 · Under review · Assigned R · 2/4 documents accepted · 1/5 checks passed')}`:state.screen==='correction'?`${t('الحالة المعروضة','Displayed state')}: ${ltr(`Corrections requested · amount ${state.fields.correctionAmount} · replacement prepared ${state.replacement}`)}`:state.screen==='queue'?`${t('الحالة المعروضة','Displayed state')}: ${ltr(`12 records · page ${state.page} · filter ${state.filter} · sort ${state.sort}`)}`:''}</footer></main></div></div>`;
}
function controls(){return `<div class="control-bar" aria-label="Visual prototype controls"><div class="arrows"><button data-action="previous" aria-label="Previous visual direction">←</button><div class="switch-name"><strong>${state.variant} · ${variants[state.variant].name()}</strong><br><small>${t('مقارنة بصرية · مؤقت','VISUAL COMPARISON · THROWAWAY')}</small></div><button data-action="next" aria-label="Next visual direction">→</button></div><span class="divider"></span><label class="control-label" for="screen-select">${t('المشهد','Scene')}</label><select id="screen-select" aria-label="${t('اختر المشهد','Choose scene')}">${Object.keys(labels).map(k=>`<option value="${k}" ${state.screen===k?'selected':''}>${labels[k]()}</option>`).join('')}</select><button data-action="language" lang="${state.lang==='ar'?'en':'ar'}">${t('English','العربية')}</button></div>`;}
function render(focus){
  document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.body.dataset.variant=state.variant;
  const screens={form:application,correction,queue,review,gallery};
  $('#app').innerHTML=shell(screens[state.screen]());$('#prototype-controls').innerHTML=localPreview?controls():'';
  document.title=`${state.variant} · ${variants[state.variant].name()} · ${labels[state.screen]()} · RIFD prototype`;
  const q=new URLSearchParams({variant:state.variant,screen:state.screen,lang:state.lang});history.replaceState(null,'',`?${q}`);
  if(focus)document.querySelector(focus)?.focus({preventScroll:true});
  console.info('Visual prototype state',{...state,fields:{...state.fields},persistence:false});
}
let feedbackTimer;
function toast(text){$('#feedback').textContent=text;$('#feedback').classList.add('visible');clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>$('#feedback').classList.remove('visible'),4500);}
function modal(title,body){$('#preview').innerHTML=`<div class="dialog-head"><h2 id="preview-title">${title}</h2>${btn(t('إغلاق','Close'),'close','small','autofocus')}</div>${body}`;$('#preview').showModal();$('#preview [autofocus]').focus();}
function navigate(screen){state.screen=screen;state.error=false;render('#main');window.scrollTo(0,0);}
function cycle(delta){state.variant=['A','B','C'][(('ABC'.indexOf(state.variant)+delta+3)%3)];render(`[data-action="${delta<0?'previous':'next'}"]`);}
document.addEventListener('click',event=>{
  const screen=event.target.closest('[data-screen]');if(screen){event.preventDefault();navigate(screen.dataset.screen);return;}
  const button=event.target.closest('[data-action]');if(!button)return;
  const action=button.dataset.action;
  if(action==='previous'||action==='next')return cycle(action==='previous'?-1:1);
  if(action==='language'){state.lang=state.lang==='ar'?'en':'ar';render('[data-action="language"]');return;}
  if(action==='page'){state.page=Number(button.dataset.page);render(`[data-page="${state.page}"]`);return;}
  if(action==='close')return $('#preview').close();
  if(action==='save')return toast(t('معاينة فقط. لم يُحفظ شيء؛ تبقى المدخلات في الذاكرة حتى تحديث الصفحة.','Preview only. Nothing saved; inputs remain in memory until refresh.'));
  if(action==='validate'){
    const length=Array.from(state.fields.explanation.trim()).length;
    state.error=length<20||length>500;render(state.error?'#explanation':'#main');
    if(!state.error)modal(t('المستندات المحفوظة في المسودة','Documents saved with the draft'),`<p class="notice">${t('هذه معاينة للمستندات. انتقال الخطوات الكامل يُراجع في قرار تدفق الشاشات.','This is a document preview. Full step transitions belong to the screen-flow decision.')}</p>${draftDocuments()}`);
    return;
  }
  if(action==='applicant-docs')return modal(t('مستندات مسودة المخزون','Inventory draft documents'),draftDocuments());
  if(action==='doc'){
    const index=Number(button.dataset.doc);state.document=index;
    if(state.screen==='review'&&state.variant!=='A'&&!button.textContent.includes(t('تكبير','Expand'))){render(`[data-doc="${index}"]`);return;}
    return modal(t(...docs[index].label),documentSheet(index));
  }
  if(action==='draft-doc')return modal(t('مستند خيالي','Fictional document'),`<article class="paper-doc"><span class="stamp">DEMO / تجريبي</span><h2>${esc(button.dataset.label)}</h2><p>${entered('مريم سالم')} · ${entered('متجر السهل التجريبي')}</p><div class="rule"></div><p>${t('مستند محفوظ ضمن المسودة، لم يُرسل للمراجعة.','Saved with the draft, not submitted for review.')}</p><dl>${definition(t('تكلفة الشراء','Purchase budget'),money(250000))}</dl></article>`);
  if(action==='replacement'){state.replacement=true;render('[data-action="replacement"]');return toast(t('جُهّز مثال بديل في الذاكرة. لم يُحفظ أو يُرسل.','Sample replacement prepared in memory. Not saved or submitted.'));}
  if(action==='stock-preview')return modal(t('خطة شراء المخزون','Stock purchase plan'),`<article class="paper-doc"><span class="stamp">DEMO / تجريبي</span><h2>${t('خطة شراء المخزون','Stock purchase plan')}</h2><p>${entered('هدى علي')} · ${entered('متجر الندى التجريبي')}</p><div class="rule"></div>${state.replacement?`<p>${t('مستلزمات منزلية لتجديد مخزون المتجر.','Household supplies to replenish business stock.')}</p><p class="amount">${money(650000)}</p>`:`<div class="notice warning">${t('مثال أصلي غير مقروء. يلزم استبداله بخطة واضحة.','Unreadable original sample. A readable replacement is required.')}</div>`}</article>`);
  if(action==='resubmit'||action==='review-action')return toast(t('هذا عرض بصري للإجراء فقط. لم تتغير حالة الطلب أو نتائج المراجعة.','Visual action preview only. No application state or review outcome changed.'));
  if(action==='sample')return toast(t('عينة لعرض شكل الإجراء وحالة التركيز.','A sample of the action and focus treatment.'));
  if(action==='open-review'){$('#preview').close();return navigate('review');}
  if(action==='record'){
    const r=records.find(r=>r.id===button.dataset.id);
    return modal(ltr(r.id),`<div class="row between"><h3>${entered(r.name)}</h3>${badge(r.status)}</div><p class="muted">${entered(r.business)}</p><dl style="margin:20px 0">${definition(t('المنتج','Product'),product(r.product))}${definition(t('المبلغ','Amount'),money(r.amount))}${definition(t('المراجع','Reviewer'),assignment(r.owner))}${definition(t('تاريخ التقديم','Submitted'),date(r.date))}</dl>${r.id==='RF-2026-1006'?btn(t('فتح نموذج مراجعة هذا الطلب','Open this application’s review sample'),'open-review','primary'):`<p class="notice">${t('هذه بطاقة معاينة. مشهد المراجعة الكامل في شريط المقارنة يخص الطلب RF-2026-1006.','This is a snapshot. The full review scene in the comparison bar uses RF-2026-1006.')}</p>`}`);
  }
});
function draftDocuments(){return [['إثبات هوية المتقدم','Applicant identity evidence','identity_Mariam.pdf'],['إثبات النشاط التجاري','Business evidence','business_السهل.pdf'],['ملخص الإيرادات والمصروفات','Revenue and expense summary','financial_Jul-Sep.pdf'],['خطة شراء المخزون','Stock purchase plan','stock_خطة.pdf']].map(([ar,en,file])=>`<div class="doc-row"><div class="file-icon">${icon('file')}</div><div class="grow"><h3>${t(ar,en)}</h3><div class="filename">${ltr(file)}</div><span class="tag">${t('محفوظ في المسودة','Saved with draft')}</span></div>${btn(t('معاينة','Preview'),'draft-doc','small',`data-label="${esc(t(ar,en))}"`)}</div>`).join('');}
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.dataset.field){state.fields[el.dataset.field]=el.value; if(el.dataset.field==='amount'&&state.screen==='form')$('.summary-card').outerHTML=summary();}
  if(el.id==='note')state.note=el.value;
  if(el.id==='queue-search'){state.search=el.value;state.page=1;const cursor=el.selectionStart;render('#queue-search');$('#queue-search').setSelectionRange(cursor,cursor);}
});
document.addEventListener('change',event=>{
  const el=event.target;if(el.dataset.field){state.fields[el.dataset.field]=el.value;if(el.id==='term')$('.summary-card').outerHTML=summary();}
  if(el.id==='screen-select')navigate(el.value);
  if(el.id==='status-filter'){state.filter=el.value;state.page=1;render('#status-filter');}
  if(el.id==='queue-sort'){state.sort=el.value;state.page=1;render('#queue-sort');}
});
document.addEventListener('keydown',event=>{
  if(event.altKey||event.ctrlKey||event.metaKey||event.shiftKey||event.target.closest('input,textarea,select,[contenteditable],[role="slider"],dialog'))return;
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();cycle(event.key==='ArrowRight'?1:-1);}
});
render();
